    35→import javax.lang.model.element.ExecutableElement;
    36→import javax.lang.model.element.Modifier;
    37→import javax.lang.model.element.PackageElement;
    38→import javax.lang.model.element.TypeElement;
    39→import javax.lang.model.element.VariableElement;
    40→import javax.lang.model.type.TypeKind;
    41→import javax.lang.model.type.TypeMirror;
    42→import javax.lang.model.util.ElementFilter;
    43→import javax.lang.model.util.Elements;
    44→import javax.lang.model.util.SimpleElementVisitor6;
    45→
    46→import static javax.lang.model.element.ElementKind.PACKAGE;
    47→
    48→/**
    49→ * Static utility methods pertaining to {@link Element} instances.
    50→ *
    51→ * @author Gregory Kick
    52→ */
    53→@Beta
    54→public final class MoreElements {
    55→  /**
    56→   * An alternate implementation of {@link Elements#getPackageOf} that does not require an
    57→   * {@link Elements} instance.
    58→   *
    59→   * @throws NullPointerException if {@code element} is {@code null}
    60→   */
    61→  public static PackageElement getPackage(Element element) {
    62→    while (element.getKind() != PACKAGE) {
    63→      element = element.getEnclosingElement();
    64→    }
    65→    return (PackageElement) element;
    66→  }
    67→
    68→  private static final ElementVisitor<PackageElement, Void> PACKAGE_ELEMENT_VISITOR =
    69→      new SimpleElementVisitor6<PackageElement, Void>() {
    70→        @Override protected PackageElement defaultAction(Element e, Void p) {
    71→          throw new IllegalArgumentException();
    72→        }
    73→
    74→        @Override public PackageElement visitPackage(PackageElement e, Void p) {
    75→          return e;
    76→        }
    77→      };
    78→
    79→  /**
    80→   * Returns the given {@link Element} instance as {@link PackageElement}.
    81→   *
    82→   * <p>This method is functionally equivalent to an {@code instanceof} check and a cast, but should
    83→   * always be used over that idiom as instructed in the documentation for {@link Element}.
    84→   *
    85→   * @throws NullPointerException if {@code element} is {@code null}
    86→   * @throws IllegalArgumentException if {@code element} isn't a {@link PackageElement}.
    87→   */
    88→  public static PackageElement asPackage(Element element) {
    89→    return element.accept(PACKAGE_ELEMENT_VISITOR, null);
    90→  }
    91→
    92→  private static final ElementVisitor<TypeElement, Void> TYPE_ELEMENT_VISITOR =
    93→      new SimpleElementVisitor6<TypeElement, Void>() {
    94→        @Override protected TypeElement defaultAction(Element e, Void p) {
    95→          throw new IllegalArgumentException();
    96→        }
    97→
    98→        @Override public TypeElement visitType(TypeElement e, Void p) {
    99→          return e;
   100→        }
   101→      };
   102→
   103→  /**
   104→   * Returns true if the given {@link Element} instance is a {@link TypeElement}.
   105→   *
   106→   * <p>This method is functionally equivalent to an {@code instanceof} check, but should
   107→   * always be used over that idiom as instructed in the documentation for {@link Element}.
   108→   *
   109→   * @throws NullPointerException if {@code element} is {@code null}
   110→   */
   111→  public static boolean isType(Element element) {
   112→    return element.getKind().isClass() || element.getKind().isInterface();
   113→  }
   114→
   115→  /**
   116→   * Returns the given {@link Element} instance as {@link TypeElement}.
   117→   *
   118→   * <p>This method is functionally equivalent to an {@code instanceof} check and a cast, but should
   119→   * always be used over that idiom as instructed in the documentation for {@link Element}.
   120→   *
   121→   * @throws NullPointerException if {@code element} is {@code null}
   122→   * @throws IllegalArgumentException if {@code element} isn't a {@link TypeElement}.
   123→   */
   124→  public static TypeElement asType(Element element) {
   125→    return element.accept(TYPE_ELEMENT_VISITOR, null);
   126→  }
   127→
   128→  private static final ElementVisitor<VariableElement, Void> VARIABLE_ELEMENT_VISITOR =
   129→      new SimpleElementVisitor6<VariableElement, Void>() {
   130→        @Override protected VariableElement defaultAction(Element e, Void p) {
   131→          throw new IllegalArgumentException();
   132→        }
   133→
   134→        @Override public VariableElement visitVariable(VariableElement e, Void p) {
   135→          return e;
   136→        }
   137→      };
   138→
   139→  /**
   140→   * Returns the given {@link Element} instance as {@link VariableElement}.
   141→   *
   142→   * <p>This method is functionally equivalent to an {@code instanceof} check and a cast, but should
   143→   * always be used over that idiom as instructed in the documentation for {@link Element}.
   144→   *
   145→   * @throws NullPointerException if {@code element} is {@code null}
   146→   * @throws IllegalArgumentException if {@code element} isn't a {@link VariableElement}.
   147→   */
   148→  public static VariableElement asVariable(Element element) {
   149→    return element.accept(VARIABLE_ELEMENT_VISITOR, null);
   150→  }
   151→
   152→  private static final ElementVisitor<ExecutableElement, Void> EXECUTABLE_ELEMENT_VISITOR =
   153→      new SimpleElementVisitor6<ExecutableElement, Void>() {
   154→        @Override protected ExecutableElement defaultAction(Element e, Void p) {
   155→          throw new IllegalArgumentException();
   156→        }
   157→
   158→        @Override public ExecutableElement visitExecutable(ExecutableElement e, Void p) {
   159→          return e;
   160→        }
   161→      };
   162→
   163→  /**
   164→   * Returns the given {@link Element} instance as {@link ExecutableElement}.
   165→   *
   166→   * <p>This method is functionally equivalent to an {@code instanceof} check and a cast, but should
   167→   * always be used over that idiom as instructed in the documentation for {@link Element}.
   168→   *
   169→   * @throws NullPointerException if {@code element} is {@code null}
   170→   * @throws IllegalArgumentException if {@code element} isn't a {@link ExecutableElement}.
   171→   */
   172→  public static ExecutableElement asExecutable(Element element) {
   173→    return element.accept(EXECUTABLE_ELEMENT_VISITOR, null);
   174→  }
   175→
   176→  /**
   177→   * Returns {@code true} iff the given element has an {@link AnnotationMirror} whose
   178→   * {@linkplain AnnotationMirror#getAnnotationType() annotation type} has the same canonical name
   179→   * as that of {@code annotationClass}. This method is a safer alternative to calling
   180→   * {@link Element#getAnnotation} and checking for {@code null} as it avoids any interaction with
   181→   * annotation proxies.
   182→   */
   183→  public static boolean isAnnotationPresent(Element element,
   184→      Class<? extends Annotation> annotationClass) {
   185→    return getAnnotationMirror(element, annotationClass).isPresent();
   186→  }
   187→
   188→  /**
   189→   * Returns an {@link AnnotationMirror} for the annotation of type {@code annotationClass} on
   190→   * {@code element}, or {@link Optional#absent()} if no such annotation exists. This method is a
   191→   * safer alternative to calling {@link Element#getAnnotation} as it avoids any interaction with
   192→   * annotation proxies.
   193→   */
   194→  public static Optional<AnnotationMirror> getAnnotationMirror(Element element,
   195→      Class<? extends Annotation> annotationClass) {
   196→    String annotationClassName = annotationClass.getCanonicalName();
   197→    for (AnnotationMirror annotationMirror : element.getAnnotationMirrors()) {
   198→      TypeElement annotationTypeElement = asType(annotationMirror.getAnnotationType().asElement());
   199→      if (annotationTypeElement.getQualifiedName().contentEquals(annotationClassName)) {
   200→        return Optional.of(annotationMirror);
   201→      }
   202→    }
   203→    return Optional.absent();
   204→  }
   205→
   206→  /**
   207→   * Returns a {@link Predicate} that can be used to filter elements by {@link Modifier}.
   208→   * The predicate returns {@code true} if the input {@link Element} has all of the given
   209→   * {@code modifiers}, perhaps in addition to others.
   210→   *
   211→   * <p>Here is an example how one could get a List of static methods of a class:
   212→   * <pre>{@code
   213→   * FluentIterable.from(ElementFilter.methodsIn(clazzElement.getEnclosedElements()))
   214→   *     .filter(MoreElements.hasModifiers(Modifier.STATIC).toList();
   215→   * }</pre>
   216→   */
   217→  public static Predicate<Element> hasModifiers(Modifier... modifiers) {
   218→    return hasModifiers(ImmutableSet.copyOf(modifiers));
   219→  }
   220→
   221→  /**
   222→   * Returns a {@link Predicate} that can be used to filter elements by {@link Modifier}.
   223→   * The predicate returns {@code true} if the input {@link Element} has all of the given
   224→   * {@code modifiers}, perhaps in addition to others.
   225→   *
   226→   * <p>Here is an example how one could get a List of methods with certain modifiers of a class:
   227→   * <pre>{@code
   228→   * Set<Modifier> modifiers = ...;
   229→   * FluentIterable.from(ElementFilter.methodsIn(clazzElement.getEnclosedElements()))
   230→   *     .filter(MoreElements.hasModifiers(modifiers).toList();}
   231→   * </pre>
   232→   */
   233→  public static Predicate<Element> hasModifiers(final Set<Modifier> modifiers) {
   234→    return new Predicate<Element>() {
   235→      @Override
   236→      public boolean apply(Element input) {
   237→        return input.getModifiers().containsAll(modifiers);
   238→      }
   239→    };
   240→  }
   241→
   242→  /**
   243→   * Returns the set of all non-private methods from {@code type}, including methods that it
   244→   * inherits from its ancestors. Inherited methods that are overridden are not included in the
   245→   * result. So if {@code type} defines {@code public String toString()}, the returned set will
   246→   * contain that method, but not the {@code toString()} method defined by {@code Object}.
   247→   *
   248→   * @param type the type whose own and inherited methods are to be returned
   249→   * @param elementUtils an {@link Elements} object, typically returned by
   250→   *     {@link javax.annotation.processing.AbstractProcessor#processingEnv processingEnv}<!--
   251→   *     -->.{@link javax.annotation.processing.ProcessingEnvironment.getElementUtils()
   252→   *     getElementUtils()}
   253→   */
   254→  public static ImmutableSet<ExecutableElement> getLocalAndInheritedMethods(
   255→      TypeElement type, Elements elementUtils) {
   256→    SetMultimap<String, ExecutableElement> methodMap = LinkedHashMultimap.create();
   257→    getLocalAndInheritedMethods(getPackage(type), type, methodMap);
   258→    // Find methods that are overridden. We do this using `Elements.overrides`, which means
   259→    // that it is inherently a quadratic operation, since we have to compare every method against
   260→    // every other method. We reduce the performance impact by (a) grouping methods by name, since
   261→    // a method cannot override another method with a different name, and (b) making sure that
   262→    // methods in ancestor types precede those in descendant types, which means we only have to
   263→    // check a method against the ones that follow it in that order.
   264→    Set<ExecutableElement> overridden = new LinkedHashSet<ExecutableElement>();
   265→    for (String methodName : methodMap.keySet()) {
   266→      List<ExecutableElement> methodList = ImmutableList.copyOf(methodMap.get(methodName));
   267→      for (int i = 0; i < methodList.size(); i++) {
   268→        ExecutableElement methodI = methodList.get(i);
   269→        for (int j = i + 1; j < methodList.size(); j++) {
   270→          ExecutableElement methodJ = methodList.get(j);
   271→          if (elementUtils.overrides(methodJ, methodI, type)) {
   272→            overridden.add(methodI);
   273→          }
   274→        }
   275→      }
   276→    }
   277→    Set<ExecutableElement> methods = new LinkedHashSet<ExecutableElement>(methodMap.values());
   278→    methods.removeAll(overridden);
   279→    return ImmutableSet.copyOf(methods);
   280→  }
   281→
   282→  // Add to `methods` the instance methods from `type` that are visible to code in the
   283→  // package `pkg`. This means all the instance methods from `type` itself and all instance methods
   284→  // it inherits from its ancestors, except private methods and package-private methods in other
   285→  // packages. This method does not take overriding into account, so it will add both an ancestor
   286→  // method and a descendant method that overrides it.
   287→  // `methods` is a multimap from a method name to all of the methods with that name, including
   288→  // methods that override or overload one another. Within those methods, those in ancestor types
   289→  // always precede those in descendant types.
   290→  private static void getLocalAndInheritedMethods(
   291→      PackageElement pkg, TypeElement type, SetMultimap<String, ExecutableElement> methods) {
   292→    for (TypeMirror superInterface : type.getInterfaces()) {
   293→      getLocalAndInheritedMethods(pkg, MoreTypes.asTypeElement(superInterface), methods);
   294→    }
   295→    if (type.getSuperclass().getKind() != TypeKind.NONE) {
   296→      // Visit the superclass after superinterfaces so we will always see the implementation of a
   297→      // method after any interfaces that declared it.
   298→      getLocalAndInheritedMethods(pkg, MoreTypes.asTypeElement(type.getSuperclass()), methods);
   299→    }
   300→    for (ExecutableElement method : ElementFilter.methodsIn(type.getEnclosedElements())) {
   301→      if (!method.getModifiers().contains(Modifier.STATIC)
   302→          && methodVisibleFromPackage(method, pkg)) {
   303→        methods.put(method.getSimpleName().toString(), method);
   304→      }
   305→    }
   306→  }
   307→
   308→  private static boolean methodVisibleFromPackage(ExecutableElement method, PackageElement pkg) {
   309→    // We use Visibility.ofElement rather than .effectiveVisibilityOfElement because it doesn't
   310→    // really matter whether the containing class is visible. If you inherit a public method
   311→    // then you have a public method, regardless of whether you inherit it from a public class.
   312→    Visibility visibility = Visibility.ofElement(method);
   313→    switch (visibility) {
   314→      case PRIVATE:
   315→        return false;
   316→      case DEFAULT:
   317→        return getPackage(method).equals(pkg);
   318→      default:
   319→        return true;
   320→    }
   321→  }
   322→
   323→  private MoreElements() {}
   324→}
