    71→public final class MoreTypes {
    72→  private static final Equivalence<TypeMirror> TYPE_EQUIVALENCE = new Equivalence<TypeMirror>() {
    73→    @Override
    74→    protected boolean doEquivalent(TypeMirror a, TypeMirror b) {
    75→      return MoreTypes.equal(a, b, ImmutableSet.<ComparedElements>of());
    76→    }
    77→
