   363→  private static final int HASH_SEED = 17;
   364→  private static final int HASH_MULTIPLIER = 31;
   365→
   366→  private static final TypeVisitor<Integer, Set<Element>> HASH_VISITOR =
   367→      new SimpleTypeVisitor6<Integer, Set<Element>>() {
   368→          int hashKind(int seed, TypeMirror t) {
   369→            int result = seed * HASH_MULTIPLIER;
   370→            result += t.getKind().hashCode();
   371→            return result;
   372→          }
   373→
   374→          @Override
   375→          protected Integer defaultAction(TypeMirror e, Set<Element> visiting) {
   376→            return hashKind(HASH_SEED, e);
   377→          }
   378→
   379→          @Override
   380→          public Integer visitArray(ArrayType t, Set<Element> visiting) {
   381→            int result = hashKind(HASH_SEED, t);
   382→            result *= HASH_MULTIPLIER;
   383→            result += t.getComponentType().accept(this, visiting);
   384→            return result;
   385→          }
   386→
   387→          @Override
   388→          public Integer visitDeclared(DeclaredType t, Set<Element> visiting) {
   389→            Element element = t.asElement();
   390→            if (visiting.contains(element)) {
   391→              return 0;
   392→            }
   393→            Set<Element> newVisiting = new HashSet<Element>(visiting);
   394→            newVisiting.add(element);
   395→            int result = hashKind(HASH_SEED, t);
   396→            result *= HASH_MULTIPLIER;
   397→            result += t.asElement().hashCode();
   398→            result *= HASH_MULTIPLIER;
   399→            result += t.getEnclosingType().accept(this, newVisiting);
   400→            result *= HASH_MULTIPLIER;
   401→            result += hashList(t.getTypeArguments(), newVisiting);
   402→            return result;
   403→          }
   404→
   405→          @Override
   406→          public Integer visitExecutable(ExecutableType t, Set<Element> visiting) {
   407→            int result = hashKind(HASH_SEED, t);
   408→            result *= HASH_MULTIPLIER;
   409→            result += hashList(t.getParameterTypes(), visiting);
   410→            result *= HASH_MULTIPLIER;
   411→            result += t.getReturnType().accept(this, visiting);
   412→            result *= HASH_MULTIPLIER;
   413→            result += hashList(t.getThrownTypes(), visiting);
   414→            result *= HASH_MULTIPLIER;
   415→            result += hashList(t.getTypeVariables(), visiting);
   416→            return result;
   417→          }
   418→
   419→          @Override
   420→          public Integer visitTypeVariable(TypeVariable t, Set<Element> visiting) {
   421→            int result = hashKind(HASH_SEED, t);
   422→            result *= HASH_MULTIPLIER;
   423→            result += t.getLowerBound().accept(this, visiting);
   424→            TypeParameterElement element = (TypeParameterElement) t.asElement();
   425→            for (TypeMirror bound : element.getBounds()) {
   426→              result *= HASH_MULTIPLIER;
   427→              result += bound.accept(this, visiting);
   428→            }
   429→            return result;
   430→          }
   431→
   432→          @Override
   433→          public Integer visitWildcard(WildcardType t, Set<Element> visiting) {
   434→            int result = hashKind(HASH_SEED, t);
   435→            result *= HASH_MULTIPLIER;
   436→            result +=
   437→                (t.getExtendsBound() == null) ? 0 : t.getExtendsBound().accept(this, visiting);
   438→            result *= HASH_MULTIPLIER;
   439→            result += (t.getSuperBound() == null) ? 0 : t.getSuperBound().accept(this, visiting);
   440→            return result;
   441→          }
   442→
   443→          @Override
   444→          public Integer visitUnknown(TypeMirror t, Set<Element> visiting) {
   445→            throw new UnsupportedOperationException();
   446→          }
   447→      };
   448→
   449→  private static int hashList(List<? extends TypeMirror> mirrors, Set<Element> visiting) {
   450→    int result = HASH_SEED;
   451→    for (TypeMirror mirror : mirrors) {
   452→      result *= HASH_MULTIPLIER;
   453→      result += hash(mirror, visiting);
   454→    }
   455→    return result;
   456→  }
   457→
   458→  private static int hash(TypeMirror mirror, Set<Element> visiting) {
   459→    return mirror == null ? 0 : mirror.accept(HASH_VISITOR, visiting);
   460→  }
