   521→  private static final TypeVisitor<Element, Void> AS_ELEMENT_VISITOR =
   522→      new SimpleTypeVisitor6<Element, Void>() {
   523→        @Override protected Element defaultAction(TypeMirror e, Void p) {
   524→          throw new IllegalArgumentException(e + "cannot be converted to an Element");
   525→        }
   526→
   527→        @Override public Element visitDeclared(DeclaredType t, Void p) {
   528→          return t.asElement();
   529→        }
   530→
   531→        @Override public Element visitError(ErrorType t, Void p) {
   532→          return t.asElement();
   533→        }
   534→
   535→        @Override public Element visitTypeVariable(TypeVariable t, Void p) {
   536→          return t.asElement();
   537→        }
   538→      };
