   602→  /**
   603→   * Returns a {@link NoType} if the {@link TypeMirror} represents an non-type such
   604→   * as void, or package, etc. or throws an {@link IllegalArgumentException}.
   605→   */
   606→  public static NoType asNoType(TypeMirror maybeNoType) {
   607→    return maybeNoType.accept(new CastingTypeVisitor<NoType>() {
   608→      @Override public NoType visitNoType(NoType noType, String p) {
   609→        return noType;
   610→      }
   611→    }, "non-type");
   612→  }
   613→
   614→  /**
   615→   * Returns a {@link NullType} if the {@link TypeMirror} represents the null type
   616→   * or throws an {@link IllegalArgumentException}.
   617→   */
   618→  public static NullType asNullType(TypeMirror maybeNullType) {
   619→    return maybeNullType.accept(new CastingTypeVisitor<NullType>() {
   620→      @Override public NullType visitNull(NullType nullType, String p) {
   621→        return nullType;
   622→      }
   623→    }, "null");
   624→  }
   625→
   626→  /**
   627→   * Returns a {@link PrimitiveType} if the {@link TypeMirror} represents a primitive type
   628→   * or throws an {@link IllegalArgumentException}.
   629→   */
   630→  public static PrimitiveType asPrimitiveType(TypeMirror maybePrimitiveType) {
   631→    return maybePrimitiveType.accept(new CastingTypeVisitor<PrimitiveType>() {
   632→      @Override public PrimitiveType visitPrimitive(PrimitiveType type, String p) {
   633→        return type;
   634→      }
   635→    }, "primitive type");
   636→  }
   637→
   638→  //
   639→  // visitUnionType would go here, but it is a 1.7 API.
   640→  //
   641→
   642→  /**
   643→   * Returns a {@link TypeVariable} if the {@link TypeMirror} represents a type variable
   644→   * or throws an {@link IllegalArgumentException}.
   645→   */
   646→  public static TypeVariable asTypeVariable(TypeMirror maybeTypeVariable) {
   647→    return maybeTypeVariable.accept(new CastingTypeVisitor<TypeVariable>() {
   648→      @Override public TypeVariable visitTypeVariable(TypeVariable type, String p) {
   649→        return type;
   650→      }
   651→    }, "type variable");
   652→  }
   653→
   654→  /**
   655→   * Returns a {@link WildcardType} if the {@link TypeMirror} represents a wildcard type
   656→   * or throws an {@link IllegalArgumentException}.
   657→   */
   658→  public static WildcardType asWildcard(WildcardType maybeWildcardType) {
   659→    return maybeWildcardType.accept(new CastingTypeVisitor<WildcardType>() {
   660→      @Override public WildcardType visitWildcard(WildcardType type, String p) {
   661→        return type;
   662→      }
   663→    }, "wildcard type");
   664→  }
   665→
   666→  /**
   667→   * Returns true if the raw type underlying the given {@link TypeMirror} represents a type that can
   668→   * be referenced by a {@link Class}. If this returns true, then {@link #isTypeOf} is guaranteed to
   669→   * not throw.
   670→   */
   671→  public static boolean isType(TypeMirror type) {
   672→    return type.accept(new SimpleTypeVisitor6<Boolean, Void>() {
   673→      @Override protected Boolean defaultAction(TypeMirror type, Void ignored) {
   674→        return false;
   675→      }
   676→
   677→      @Override public Boolean visitNoType(NoType noType, Void p) {
   678→        return noType.getKind().equals(TypeKind.VOID);
   679→      }
   680→
   681→      @Override public Boolean visitPrimitive(PrimitiveType type, Void p) {
   682→        return true;
   683→      }
   684→
   685→      @Override public Boolean visitArray(ArrayType array, Void p) {
   686→        return true;
   687→      }
   688→
   689→      @Override public Boolean visitDeclared(DeclaredType type, Void ignored) {
   690→        return MoreElements.isType(type.asElement());
   691→      }
   692→    }, null);
   693→  }
   694→
   695→  /**
   696→   *
   697→   * Returns true if the raw type underlying the given {@link TypeMirror} represents the
   698→   * same raw type as the given {@link Class} and throws an IllegalArgumentException if the
   699→   * {@link TypeMirror} does not represent a type that can be referenced by a {@link Class}
   700→   */
   701→  public static boolean isTypeOf(final Class<?> clazz, TypeMirror type) {
   702→    checkNotNull(clazz);
   703→    return type.accept(new SimpleTypeVisitor6<Boolean, Void>() {
   704→      @Override protected Boolean defaultAction(TypeMirror type, Void ignored) {
   705→        throw new IllegalArgumentException(type + " cannot be represented as a Class<?>.");
   706→      }
   707→
   708→      @Override public Boolean visitNoType(NoType noType, Void p) {
   709→        if (noType.getKind().equals(TypeKind.VOID)) {
   710→          return clazz.equals(Void.TYPE);
   711→        }
   712→        throw new IllegalArgumentException(noType + " cannot be represented as a Class<?>.");
   713→      }
   714→
   715→      @Override public Boolean visitPrimitive(PrimitiveType type, Void p) {
   716→        switch (type.getKind()) {
   717→          case BOOLEAN:
   718→            return clazz.equals(Boolean.TYPE);
   719→          case BYTE:
   720→            return clazz.equals(Byte.TYPE);
   721→          case CHAR:
   722→            return clazz.equals(Character.TYPE);
   723→          case DOUBLE:
   724→            return clazz.equals(Double.TYPE);
   725→          case FLOAT:
   726→            return clazz.equals(Float.TYPE);
   727→          case INT:
   728→            return clazz.equals(Integer.TYPE);
   729→          case LONG:
   730→            return clazz.equals(Long.TYPE);
   731→          case SHORT:
   732→            return clazz.equals(Short.TYPE);
   733→          default:
   734→            throw new IllegalArgumentException(type + " cannot be represented as a Class<?>.");
   735→        }
   736→      }
   737→
   738→      @Override public Boolean visitArray(ArrayType array, Void p) {
   739→        return clazz.isArray()
   740→            && isTypeOf(clazz.getComponentType(), array.getComponentType());
   741→      }
   742→
   743→      @Override public Boolean visitDeclared(DeclaredType type, Void ignored) {
   744→        TypeElement typeElement;
   745→        try {
   746→          typeElement = MoreElements.asType(type.asElement());
   747→        } catch (IllegalArgumentException iae) {
   748→          throw new IllegalArgumentException(type + " does not represent a class or interface.");
   749→        }
   750→        return typeElement.getQualifiedName().contentEquals(clazz.getCanonicalName());
   751→      }
   752→    }, null);
   753→  }
   754→
   755→  /**
   756→   * Returns the non-object superclass of the type with the proper type parameters.
   757→   * An absent Optional is returned if there is no non-Object superclass.
   758→   */
   759→  public static Optional<DeclaredType> nonObjectSuperclass(final Types types, Elements elements,
   760→      DeclaredType type) {
   761→    checkNotNull(types);
   762→    checkNotNull(elements);
   763→    checkNotNull(type);
   764→
   765→    final TypeMirror objectType =
   766→        elements.getTypeElement(Object.class.getCanonicalName()).asType();
   767→    // It's guaranteed there's only a single CLASS superclass because java doesn't have multiple
   768→    // class inheritance.
   769→    TypeMirror superclass = getOnlyElement(FluentIterable.from(types.directSupertypes(type))
   770→        .filter(new Predicate<TypeMirror>() {
   771→          @Override public boolean apply(TypeMirror input) {
   772→           return input.getKind().equals(TypeKind.DECLARED)
   773→               && (MoreElements.asType(
   774→                     MoreTypes.asDeclared(input).asElement())).getKind().equals(ElementKind.CLASS)
   775→               && !types.isSameType(objectType, input);
   776→          }
   777→        }), null);
   778→    return superclass != null
   779→        ? Optional.of(MoreTypes.asDeclared(superclass))
   780→        : Optional.<DeclaredType>absent();
   781→  }
   782→
   783→  /**
   784→   * Resolves a {@link VariableElement} parameter to a method or constructor based on the given
   785→   * container, or a member of a class. For parameters to a method or constructor, the variable's
   786→   * enclosing element must be a supertype of the container type. For example, given a
   787→   * {@code container} of type {@code Set<String>}, and a variable corresponding to the {@code E e}
   788→   * parameter in the {@code Set.add(E e)} method, this will return a TypeMirror for {@code String}.
   789→   */
   790→  public static TypeMirror asMemberOf(Types types, DeclaredType container,
   791→      VariableElement variable) {
   792→    if (variable.getKind().equals(ElementKind.PARAMETER)) {
   793→      ExecutableElement methodOrConstructor =
   794→          MoreElements.asExecutable(variable.getEnclosingElement());
   795→      ExecutableType resolvedMethodOrConstructor = MoreTypes.asExecutable(
   796→          types.asMemberOf(container, methodOrConstructor));
   797→      List<? extends VariableElement> parameters = methodOrConstructor.getParameters();
   798→      List<? extends TypeMirror> parameterTypes =
   799→          resolvedMethodOrConstructor.getParameterTypes();
   800→      checkState(parameters.size() == parameterTypes.size());
   801→      for (int i = 0; i < parameters.size(); i++) {
   802→        // We need to capture the parameter type of the variable we're concerned about,
   803→        // for later printing.  This is the only way to do it since we can't use
   804→        // types.asMemberOf on variables of methods.
   805→        if (parameters.get(i).equals(variable)) {
   806→          return parameterTypes.get(i);
   807→        }
   808→      }
   809→      throw new IllegalStateException("Could not find variable: " + variable);
   810→    } else {
   811→      return types.asMemberOf(container, variable);
   812→    }
   813→  }
   814→
   815→  private static class CastingTypeVisitor<T> extends SimpleTypeVisitor6<T, String> {
   816→    @Override protected T defaultAction(TypeMirror e, String label) {
   817→      throw new IllegalArgumentException(e + " does not represent a " + label);
   818→    }
   819→  }
   820→
   821→  private MoreTypes() {}
   822→}
